                    if a != b:
                        key = (min(a, b), max(a, b))
                        if key not in edge_pair:
                            if a < b:
                                edge_pair[key] = ((r, c), (nr, nc))
                            else:
                                edge_pair[key] = ((nr, nc), (r, c))

