        base = max(comp, key=lambda rid: len(regions[rid]["cells"]))
        if len(regions[base]["cells"]) <= 1:
            continue

        # Propagate the base shape through the region adjacency tree/path
        full_shape = {base: regions[base]["cells"][:]}
        seen = {base}
        q = deque([base])

        while q:
            u = q.popleft()
            for v in adj[u]:
                if v in seen:
                    continue

                a, b = min(u, v), max(u, v)
                cell_a, cell_b = edge_pair[(a, b)]

                if u == a:
                    ur, uc = cell_a
                    vr, vc = cell_b
                else:
                    ur, uc = cell_b
                    vr, vc = cell_a

                dr = vr - ur
                dc = vc - uc

                full_shape[v] = [(r + dr, c + dc) for (r, c) in full_shape[u]]
                seen.add(v)
                q.append(v)

        # Paint all propagated shapes
        for rid, cells in full_shape.items():
            color = regions[rid]["color"]
